        if (pmb->pmy_mesh->ncycle == 30) {
          Real bmag = std::sqrt(SQR(bc(IB1,k,j,i)) + SQR(bc(IB2,k,j,i))
                             + SQR(bc(IB3,k,j,i)));
          if (bmag >= 1.0e-3*b0) {
            refflag += 1;
          }
        }
      }
    }
  }
  if (refflag > 4) {
    return 1;
  }
  return 0;
